-- Corporate Scorecard: the 2026 strategy's 61 KPIs, cascaded to
-- departments via the RACI grid (CORE/SUPPORT), imported from the
-- ACOB_2026_Strategic_Goal_KPI_ workbook.
--
-- Department mapping decisions (per user instruction 2026-08-24):
--   Corporate Strategy (workbook) maps to BOTH Corporate Services and
--   IT and Communications (matrix) -- both take on whatever role
--   Corporate Strategy has for a given KPI.
--   Logistics, Monitoring and Evaluation, Executive Management, SIWES
--   have no workbook equivalent and get no seeded assignment -- the
--   schema still lets any department be assigned to any KPI later.
--
-- Only CORE ownership drives a department's scorecard score; SUPPORT
-- is visible and taggable but not scored.

CREATE TABLE IF NOT EXISTS public.corporate_kpis (
  id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  source_sn           integer NOT NULL UNIQUE,
  perspective         text NOT NULL,
  strategic_priority  text NOT NULL,
  strategic_objective text NOT NULL,
  measure             text NOT NULL,
  target_text         text NOT NULL,
  measure_type        text NOT NULL DEFAULT 'count',
  direction           text NOT NULL DEFAULT 'at_least',
  is_archived         boolean NOT NULL DEFAULT false,
  created_at          timestamptz NOT NULL DEFAULT now(),
  updated_at          timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT corporate_kpis_perspective_check
    CHECK (perspective IN ('Financial', 'Customer', 'Internal Process', 'Organizational Capacity')),
  CONSTRAINT corporate_kpis_measure_type_check
    CHECK (measure_type IN ('count', 'percentage', 'currency', 'milestone')),
  CONSTRAINT corporate_kpis_direction_check
    CHECK (direction IN ('at_least', 'at_most'))
);

COMMENT ON TABLE public.corporate_kpis IS
  'The 61 corporate KPIs from the 2026 strategic plan. Read-only reference; do not edit measure/target after import without updating the source workbook.';
COMMENT ON COLUMN public.corporate_kpis.source_sn IS 'S/N from the Corporate Scorecard Master sheet -- stable reference back to the source workbook.';

CREATE TABLE IF NOT EXISTS public.kpi_assignments (
  id                uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  kpi_id            uuid NOT NULL REFERENCES public.corporate_kpis(id) ON DELETE CASCADE,
  department        text NOT NULL,
  role              text NOT NULL,
  department_target text,
  proposed_action   text,
  created_at        timestamptz NOT NULL DEFAULT now(),
  updated_at        timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT kpi_assignments_role_check CHECK (role IN ('core', 'support')),
  CONSTRAINT kpi_assignments_unique UNIQUE (kpi_id, department)
);

COMMENT ON TABLE public.kpi_assignments IS
  'The RACI grid: which department owns (core) or contributes to (support) each corporate KPI. Only core rows count toward a department''s scorecard score.';
COMMENT ON COLUMN public.kpi_assignments.department IS 'Matches profiles.department / departments.name -- same free-text join the rest of the app uses.';
COMMENT ON COLUMN public.kpi_assignments.department_target IS 'This department''s own target/quota toward the corporate target, in their own words.';

CREATE INDEX IF NOT EXISTS idx_kpi_assignments_kpi ON public.kpi_assignments (kpi_id);
CREATE INDEX IF NOT EXISTS idx_kpi_assignments_department ON public.kpi_assignments (department);

CREATE TABLE IF NOT EXISTS public.kpi_actuals (
  id                    uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  kpi_id                uuid NOT NULL REFERENCES public.corporate_kpis(id) ON DELETE CASCADE,
  department            text NOT NULL,
  review_cycle_id       uuid REFERENCES public.review_cycles(id) ON DELETE SET NULL,
  actual_value          numeric,
  milestones_completed  integer,
  milestones_total      integer,
  note                  text,
  recorded_by           uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  recorded_at           timestamptz NOT NULL DEFAULT now()
);

COMMENT ON TABLE public.kpi_actuals IS
  'Time series of recorded progress against a department''s KPI target. A department''s attainment is actual / target, not task completion -- tasks are the evidence trail, not the score.';

CREATE INDEX IF NOT EXISTS idx_kpi_actuals_kpi_dept ON public.kpi_actuals (kpi_id, department, recorded_at DESC);
CREATE INDEX IF NOT EXISTS idx_kpi_actuals_cycle ON public.kpi_actuals (review_cycle_id);

-- A task may be tagged to the corporate KPI it serves. This is a label for
-- reporting and the Corporate Goal -> Department -> Task evidence trail --
-- it does not affect the task's own weight*rating score, and it replaces
-- nothing: goal_id / project_id stay as they are.
ALTER TABLE public.tasks ADD COLUMN IF NOT EXISTS kpi_id uuid REFERENCES public.corporate_kpis(id) ON DELETE SET NULL;
CREATE INDEX IF NOT EXISTS idx_tasks_kpi_id ON public.tasks (kpi_id) WHERE is_archived = false;
COMMENT ON COLUMN public.tasks.kpi_id IS 'Optional link to the corporate KPI this task''s work serves. Reporting label only -- does not affect scoring.';

-- RLS: the scorecard is an organisational index, not sensitive content, so
-- every authenticated user may read it -- exactly like portfolios. Writing
-- the KPI register itself (measure/target text) is admin-only, since that is
-- the source-of-truth import from the strategy document. Editing a
-- department's own target/proposed-action, and recording actuals, is open to
-- that department's lead as well, matching who the workbook instructs to
-- fill in the yellow cells.

ALTER TABLE public.corporate_kpis ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.kpi_assignments ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.kpi_actuals ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Corporate KPIs select authenticated" ON public.corporate_kpis;
CREATE POLICY "Corporate KPIs select authenticated"
ON public.corporate_kpis FOR SELECT TO authenticated
USING (true);

DROP POLICY IF EXISTS "Corporate KPIs write admin" ON public.corporate_kpis;
CREATE POLICY "Corporate KPIs write admin"
ON public.corporate_kpis FOR ALL TO authenticated
USING ((SELECT public.has_role('admin')))
WITH CHECK ((SELECT public.has_role('admin')));

DROP POLICY IF EXISTS "KPI assignments select authenticated" ON public.kpi_assignments;
CREATE POLICY "KPI assignments select authenticated"
ON public.kpi_assignments FOR SELECT TO authenticated
USING (true);

DROP POLICY IF EXISTS "KPI assignments write scoped" ON public.kpi_assignments;
CREATE POLICY "KPI assignments write scoped"
ON public.kpi_assignments FOR ALL TO authenticated
USING (
  (SELECT public.has_role('admin'))
  OR EXISTS (
    SELECT 1 FROM public.profiles p
    WHERE p.id = auth.uid()
      AND p.is_department_lead
      AND (
        p.department = kpi_assignments.department
        OR kpi_assignments.department = ANY(COALESCE(p.lead_departments, ARRAY[]::text[]))
      )
  )
)
WITH CHECK (
  (SELECT public.has_role('admin'))
  OR EXISTS (
    SELECT 1 FROM public.profiles p
    WHERE p.id = auth.uid()
      AND p.is_department_lead
      AND (
        p.department = kpi_assignments.department
        OR kpi_assignments.department = ANY(COALESCE(p.lead_departments, ARRAY[]::text[]))
      )
  )
);

DROP POLICY IF EXISTS "KPI actuals select authenticated" ON public.kpi_actuals;
CREATE POLICY "KPI actuals select authenticated"
ON public.kpi_actuals FOR SELECT TO authenticated
USING (true);

DROP POLICY IF EXISTS "KPI actuals write scoped" ON public.kpi_actuals;
CREATE POLICY "KPI actuals write scoped"
ON public.kpi_actuals FOR ALL TO authenticated
USING (
  (SELECT public.has_role('admin'))
  OR EXISTS (
    SELECT 1 FROM public.profiles p
    WHERE p.id = auth.uid()
      AND p.is_department_lead
      AND (
        p.department = kpi_actuals.department
        OR kpi_actuals.department = ANY(COALESCE(p.lead_departments, ARRAY[]::text[]))
      )
  )
)
WITH CHECK (
  (SELECT public.has_role('admin'))
  OR EXISTS (
    SELECT 1 FROM public.profiles p
    WHERE p.id = auth.uid()
      AND p.is_department_lead
      AND (
        p.department = kpi_actuals.department
        OR kpi_actuals.department = ANY(COALESCE(p.lead_departments, ARRAY[]::text[]))
      )
  )
);

GRANT SELECT ON public.corporate_kpis TO authenticated;
GRANT SELECT ON public.kpi_assignments TO authenticated;
GRANT SELECT ON public.kpi_actuals TO authenticated;

